bounded_host_request.command:
set -euo pipefail
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 61
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import {readFileSync} from 'node:fs';
import {setDefaultResultOrder} from 'node:dns';
import {setDefaultAutoSelectFamily} from 'node:net';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
import {createGateOwner} from './owner/gateOwner.mjs';
setDefaultResultOrder('ipv4first');
setDefaultAutoSelectFamily(false);
try{
 const token=readFileSync('/run/secrets/videobot_telegram_token','utf8').trim();
 const api=createTelegramBotApi({token,timeoutMs:15000});
 const owner=await createGateOwner({telegramApi:api,pool:{query:async()=>{throw Error('READ_ONLY_QUERY_NOT_PERMITTED');}}});
 const topic=await owner.getVerifiedStickerTopic();
 if(topic.chatId!==-1002373696859||topic.threadId!==4640||topic.purpose!=='sticker')process.exit(71);
 console.log('CREATEVDOBOT_VERIFIED_STICKER_TOPIC=PASS');
 console.log('THREAD_4640=VERIFIED');
}catch{console.log('CREATEVDOBOT_VERIFIED_STICKER_TOPIC=FAILED');process.exitCode=72;}
NODE
